                    [row[:c] for row in grid],
                    [row[c + 1:] for row in grid],
                )
                break

    first, second = parts
    def count_color(part, color):
        return sum(v == color for row in part for v in row)

    # Color 4 identifies the intended side when it is a substantial pattern;
    # sparse 4s are distractors. In the ambiguous case use the later half.
    n1 = sum(map(len, first))
    n2 = sum(map(len, second))
    p1 = count_color(first, 4) / n1
    p2 = count_color(second, 4) / n2
    if p1 >= 0.20 and p1 > p2:
        chosen = first
    elif p2 >= 0.20 and p2 > p1:
        chosen = second
    else:
        chosen = second

    # In the 2/4 pattern, turn the 2s into the marked color and use 2
    # for the other cells.
    colors = {v for row in chosen for v in row}
    if 2 in colors and 4 in colors:
        return [[3 if v == 2 else 2 for v in row] for row in chosen]

    # Otherwise, recolor the color unique to the chosen half as 3.
    other = second if chosen is first else first
    shared = ({v for row in chosen for v in row} &
              {v for row in other for v in row})
    unique = [v for v in colors if v not in shared]
    if unique:
        foreground = unique[0]
        return [[3 if v == foreground else v for v in row] for row in chosen]

    counts = Counter(v for row in chosen for v in row)
    foreground = min(counts, key=counts.get)
